/* SmartLearn Native Color Classes */
.sl-text-primary { color: var(--smartlearn-primary) !important; }
.sl-text-emphasis { color: var(--smartlearn-text) !important; }
.sl-text-muted { color: var(--smartlearn-text-muted) !important; }
.sl-bg-main { background-color: var(--smartlearn-bg) !important; }
.sl-bg-card { background-color: var(--smartlearn-card-bg) !important; border: 1px solid var(--smartlearn-card-border) !important; }
.sl-bg-primary { background-color: var(--smartlearn-primary) !important; }
.sl-hero-search .sl-bg-primary-subtle { background-color: color-mix(in srgb, var(--smartlearn-primary) 15%, transparent) !important; }
.sl-hero-search .sl-btn-primary { background-color: var(--smartlearn-btn-bg) !important; border-color: var(--smartlearn-btn-bg) !important; color: var(--smartlearn-btn-text, #ffffff) !important; }
.sl-hero-search .sl-btn-primary:hover { background-color: var(--smartlearn-btn-hover-bg, var(--smartlearn-btn-bg)) !important; filter: brightness(0.9); }
.sl-hero-search .sl-btn-outline-primary { border-color: var(--smartlearn-primary) !important; color: var(--smartlearn-primary) !important; }
.sl-hero-search .sl-btn-outline-primary:hover { background-color: var(--smartlearn-primary) !important; color: #fff !important; }
.sl-border-primary { border-color: var(--smartlearn-primary) !important; }
.sl-hero-search {
    background-color: var(--bs-secondary-bg);
    min-height: 80vh;
    display: flex;
    align-items: center;
    position: relative;
}
.sl-hero-search::before {
    content: ''; position: absolute; inset: 0;
    background: radial-gradient(circle at 50% 0%, rgba(13, 110, 253, 0.05) 0%, transparent 70%);
}
.sl-hero-search .sl-search-title {
    letter-spacing: -0.02em;
}
.sl-hero-search .search-box {
    box-shadow: 
        inset 0 0 0 1px rgba(255, 255, 255, 0.1),
        8px 8px 16px rgba(0, 0, 0, 0.06),
        -8px -8px 16px rgba(255, 255, 255, 0.1);
    transition: all 0.3s ease;
}
.sl-hero-search .search-box:focus-within {
    box-shadow: 
        inset 0 0 0 2px var(--smartlearn-primary),
        10px 10px 20px rgba(0, 0, 0, 0.1),
        -10px -10px 20px rgba(255, 255, 255, 0.1);
    transform: translateY(-2px);
}
.sl-hero-search .sl-search-input:focus {
    outline: none;
}
.sl-hero-search .sl-search-input::placeholder {
    color: var(--bs-secondary-color);
}
.sl-hero-search .search-dropdown {
    z-index: 10;
    opacity: 0;
    transform: translateY(10px);
    transition: all 0.3s ease;
}
.sl-hero-search .search-box:focus-within ~ .search-dropdown {
    display: block !important;
    opacity: 1;
    transform: translateY(0);
}
.sl-hero-search .sl-tag {
    box-shadow: 4px 4px 10px rgba(0,0,0,0.03), -4px -4px 10px rgba(255,255,255,0.1);
    transition: all 0.2s ease;
}
.sl-hero-search .sl-tag:hover {
    transform: translateY(-2px);
    box-shadow: 6px 6px 12px rgba(0,0,0,0.05), -6px -6px 12px rgba(255,255,255,0.9);
    color: var(--smartlearn-primary) !important;
}
.sl-hero-search .tracking-wide {
    letter-spacing: 0.1em;
}

js:
(function() {
    const root = document.querySelector('.sl-hero-search');
    if (!root) return;
    const playBtns = root.querySelectorAll('.sl-play-btn, .sl-item-play-btn, .sl-play-overlay, [class*="play"]');
    playBtns.forEach(btn => {
        btn.addEventListener('click', (e) => {
            if (document.body.classList.contains('sl-editor-mode')) return;
            e.preventDefault();
            const container = btn.closest('.position-relative') || btn.parentElement;
            const urlEl = root.querySelector('.sl-item-video-url');
            const videoUrl = urlEl ? urlEl.innerText.trim() : 'https://www.youtube.com/embed/dQw4w9WgXcQ';
            if (!container || !videoUrl) return;

            const poster = container.querySelector('img');
            if (poster) poster.style.display = 'none';
            btn.style.display = 'none';

            const iframe = document.createElement('iframe');
            iframe.src = videoUrl + (videoUrl.includes('?') ? '&' : '?') + 'autoplay=1';
            iframe.style.position = 'absolute';
            iframe.style.top = '0';
            iframe.style.left = '0';
            iframe.style.width = '100%';
            iframe.style.height = '100%';
            iframe.style.border = 'none';
            iframe.setAttribute('allow', 'autoplay; fullscreen; encrypted-media');
            iframe.setAttribute('allowfullscreen', 'true');
            container.appendChild(iframe);
        });
    });
})();
